changeSet.sql:
ALTER TABLE club_banned_players ENABLE ROW LEVEL SECURITY;
-- Club admins and owners can see all bans for their club CREATE POLICY club_banned_players_select_admin ON club_banned_players FOR SELECT TO authenticated USING ( EXISTS ( SELECT 1 FROM club_memberships cm WHERE cm.club_id = club_banned_players.club_id AND cm.player_id = auth.uid() AND cm.role IN ('owner', 'admin') ) );
-- Players can see if they are banned CREATE POLICY club_banned_players_select_self ON club_banned_players FOR SELECT TO authenticated USING (player_id = auth.uid());
-- Only club admins/owners can insert bans CREATE POLICY club_banned_players_insert ON club_banned_players FOR INSERT TO authenticated WITH CHECK ( EXISTS ( SELECT 1 FROM club_memberships cm WHERE cm.club_id = club_banned_players.club_id AND cm.player_id = auth.uid() AND cm.role IN ('owner', 'admin') ) );
-- Only club admins/owners can delete bans CREATE POLICY club_banned_players_delete ON club_banned_players FOR DELETE TO authenticated USING ( EXISTS ( SELECT 1 FROM club_memberships cm WHERE cm.club_id = club_banned_players.club_id AND cm.player_id = auth.uid() AND cm.role IN ('owner', 'admin') ) );

changeSet.rollback:
DROP POLICY IF EXISTS club_banned_players_select_admin ON club_banned_players;
DROP POLICY IF EXISTS club_banned_players_select_self ON club_banned_players;
DROP POLICY IF EXISTS club_banned_players_insert ON club_banned_players;
DROP POLICY IF EXISTS club_banned_players_delete ON club_banned_players;
ALTER TABLE club_banned_players DISABLE ROW LEVEL SECURITY;
